    # Expands with `getbyte`, without `unpack`.
    def self.expand_i32(s)
      n = s.bytesize / 4
      a = Array.new(n, 0)
      i = 0
      while i < n
        o = i * 4
        v = s.getbyte(o) | (s.getbyte(o + 1) << 8) |
            (s.getbyte(o + 2) << 16) | (s.getbyte(o + 3) << 24)
        a[i] = v >= 0x80000000 ? v - 0x100000000 : v
        i += 1
      end
      a
    end

    def self.column(bin, stride, k)
      n = bin.bytesize / (stride * 4)
      a = Array.new(n, 0)
      i = 0
      while i < n
        o = (i * stride + k) * 4
        v = bin.getbyte(o) | (bin.getbyte(o + 1) << 8) |
            (bin.getbyte(o + 2) << 16) | (bin.getbyte(o + 3) << 24)
        a[i] = v >= 0x80000000 ? v - 0x100000000 : v
        i += 1
      end
      a
    end

