    def self.mobj_missilestate; column(MOBJINFO2_BIN, 23, 11); end
    def self.mobj_deathstate;   column(MOBJINFO2_BIN, 23, 12); end
    def self.mobj_xdeathstate;  column(MOBJINFO2_BIN, 23, 13); end
    def self.mobj_deathsound;   column(MOBJINFO2_BIN, 23, 14); end
    def self.mobj_speed;        column(MOBJINFO2_BIN, 23, 15); end
    def self.mobj_mass;         column(MOBJINFO2_BIN, 23, 18); end
    def self.mobj_damage;       column(MOBJINFO2_BIN, 23, 19); end
    def self.mobj_activesound;  column(MOBJINFO2_BIN, 23, 20); end
    def self.mobj_raisestate;   column(MOBJINFO2_BIN, 23, 22); end

    # The 6 columns of weaponinfo[] (ammo/upstate/downstate/readystate/atkstate/flashstate).
    def self.weapon_ammo;       column(WEAPONINFO_BIN, 6, 0); end
    def self.weapon_upstate;    column(WEAPONINFO_BIN, 6, 1); end
    def self.weapon_downstate;  column(WEAPONINFO_BIN, 6, 2); end
    def self.weapon_readystate; column(WEAPONINFO_BIN, 6, 3); end
    def self.weapon_atkstate;   column(WEAPONINFO_BIN, 6, 4); end
    def self.weapon_flashstate; column(WEAPONINFO_BIN, 6, 5); end

    # Sprite names, cut 4 characters at a time.
    def self.sprnames
      n = SPRNAMES.bytesize / 4
      a = Array.new(n, "")
      i = 0
      while i < n
        a[i] = SPRNAMES.byteslice(i * 4, 4)
        i += 1
      end
      a
    end
  end
end
